-- Optional Oracle 23ai fixture for SQL BOOLEAN metadata.
-- Run only on versions that support BOOLEAN as a SQL data type.

SET DEFINE OFF
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

BEGIN
  EXECUTE IMMEDIATE 'DROP TABLE OC_23AI_BOOLEAN_FLAGS CASCADE CONSTRAINTS';
EXCEPTION WHEN OTHERS THEN IF SQLCODE != -942 THEN RAISE; END IF;
END;
/

CREATE TABLE OC_23AI_BOOLEAN_FLAGS (
  FLAG_ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
  IS_ENABLED BOOLEAN DEFAULT TRUE NOT NULL,
  NOTES VARCHAR2(100),
  CONSTRAINT OC_23AI_BOOLEAN_FLAGS_PK PRIMARY KEY (FLAG_ID)
);

COMMENT ON TABLE OC_23AI_BOOLEAN_FLAGS IS '23ai SQL BOOLEAN fixture for oracode';

PROMPT Optional 23ai BOOLEAN fixture loaded
